				$('tr[data-group|="f"]').length,
				1,
				"Check that is 1 header row (implying 2 content row)",
			);
			checkHeaderRow($, $("tr")[0], {
				bgColor: "bg-2",
				group: "f-0",
				file: "foo.js",
				problems: "2 problems (1 error, 1 warning)",
			});
			checkContentRow($, $("tr")[1], {
				group: "f-0",
				lineCol: "5:10",
				color: "clr-2",
				message: "Unexpected foo.",
				ruleId: "foo",
			});
			checkContentRow($, $("tr")[2], {
				group: "f-0",
				lineCol: "6:11",
				color: "clr-1",
				message: "Unexpected bar.",
				ruleId: "bar",
			});
		});
	});

	describe("when passed multiple files with 1 error & warning message respectively", () => {
		const rulesMeta = {
			foo: {
				type: "problem",

				docs: {
					description: "This is rule 'foo'",
					recommended: true,
					url: "https://eslint.org/docs/rules/foo",
				},

				fixable: "code",

				messages: {
					message1: "This is a message for rule 'foo'.",
				},
			},
			bar: {
				type: "suggestion",

				docs: {
					description: "This is rule 'bar'",
					recommended: false,
				},

				messages: {
					message1: "This is a message for rule 'bar'.",
				},
			},
		};
		const code = {
			results: [
				{
					filePath: "foo.js",
					errorCount: 1,
					warningCount: 0,
					messages: [
						{
							message: "Unexpected foo.",
							severity: 2,
							line: 5,
							column: 10,
							ruleId: "foo",
							source: "foo",
						},
					],
				},
				{
					filePath: "bar.js",
					errorCount: 0,
					warningCount: 1,
					messages: [
						{
							message: "Unexpected bar.",
							severity: 1,
							line: 6,
							column: 11,
							ruleId: "bar",
							source: "bar",
						},
					],
				},
			],
			rulesMeta,
		};

		it("should return a string in HTML format with 2 issues in 2 files and styled accordingly", () => {
			const result = formatter(code.results, { rulesMeta });
			const $ = cheerio.load(result);

			// Check overview
			checkOverview($, {
				bgColor: "bg-2",
				problems: "2 problems (1 error, 1 warning)",
			});

